sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    /* ============================================================
       INITIAL STATE
       ============================================================ */

    c.searchText = '';
    c.companyFilter = '';
    c.roleFilter = '';

    c.selectedOffer = null;
    c.showDocument = false;

    c.isLoading = false;


    /* ============================================================
       INITIALIZE
       ============================================================ */

    c.$onInit = function() {

        if (!c.data)
            return;

        if (!c.data.offers)
            c.data.offers = [];

        if (!c.data.stats) {

            c.data.stats = {
                total: 0,
                thisMonth: 0,
                companies: 0
            };

        }

    };


    /* ============================================================
       ROLE

       TPO + INTERVIEWER use the admin/table view.
       ============================================================ */

    c.isTPO = function() {

        return !!(
            c.data &&
            (
                c.data.isTPO ||
                c.data.isInterviewer
            )
        );

    };


    /* ============================================================
       COMPANY USER

       ONLY INTERVIEWER.

       HR IS NOT INCLUDED.
       ============================================================ */

    c.isCompanyUser = function() {

        return !!(
            c.data &&
            c.data.isInterviewer
        );

    };


    /* ============================================================
       STUDENT
       ============================================================ */

    c.hasOffer = function() {

        return !!(
            c.data &&
            c.data.offer
        );

    };


    c.isOffered = function() {

        if (!c.hasOffer())
            return false;

        var status =
            String(
                c.data.offer.status || ''
            )
            .toLowerCase()
            .trim();


        return (
            status === 'offered' ||
            status === 'accepted' ||
            status === 'offer accepted'
        );

    };


    c.isAccepted = function() {

        if (!c.hasOffer())
            return false;

        var status =
            String(
                c.data.offer.status || ''
            )
            .toLowerCase()
            .trim();


        return (
            status === 'accepted' ||
            status === 'offer accepted'
        );

    };


    /* ============================================================
       STATUS
       ============================================================ */

    c.getStatusClass = function(status) {

        status =
            String(
                status || 'offered'
            )
            .toLowerCase()
            .trim();


        if (
            status === 'accepted' ||
            status === 'offer accepted'
        ) {

            return 'nx-status-accepted';

        }


        if (
            status === 'rejected' ||
            status === 'declined'
        ) {

            return 'nx-status-rejected';

        }


        return 'nx-status-offered';

    };


    c.getStatusLabel = function(status) {

        return status || 'Offered';

    };


    /* ============================================================
       INITIAL
       ============================================================ */

    c.getInitial = function(name) {

        if (!name)
            return 'O';

        return String(name)
            .trim()
            .charAt(0)
            .toUpperCase();

    };


    /* ============================================================
       DISPLAY VALUE
       ============================================================ */

    c.displayValue = function(
        value,
        fallback
    ) {

        if (
            value === null ||
            typeof value === 'undefined' ||
            String(value).trim() === ''
        ) {

            return fallback ||
                'Not specified';

        }

        return value;

    };


    /* ============================================================
       COMPANIES
       ============================================================ */

    c.getCompanies = function() {

        var result = {};
        var companies = [];

        if (
            !c.data ||
            !c.data.offers
        )
            return companies;


        c.data.offers.forEach(
            function(offer) {

                if (
                    offer.company &&
                    !result[
                        offer.company
                    ]
                ) {

                    result[
                        offer.company
                    ] = true;

                    companies.push(
                        offer.company
                    );

                }

            }
        );


        return companies.sort();

    };


    /* ============================================================
       ROLES
       ============================================================ */

    c.getRoles = function() {

        var result = {};
        var roles = [];

        if (
            !c.data ||
            !c.data.offers
        )
            return roles;


        c.data.offers.forEach(
            function(offer) {

                if (
                    offer.jobRole &&
                    !result[
                        offer.jobRole
                    ]
                ) {

                    result[
                        offer.jobRole
                    ] = true;

                    roles.push(
                        offer.jobRole
                    );

                }

            }
        );


        return roles.sort();

    };


    /* ============================================================
       SEARCH
       ============================================================ */

    c.matchesSearch = function(offer) {

        var search =
            String(
                c.searchText || ''
            )
            .toLowerCase()
            .trim();


        if (!search)
            return true;


        var values = [

            offer.number,
            offer.student,
            offer.company,
            offer.jobRole,
            offer.package,
            offer.offerDate

        ];


        for (
            var i = 0;
            i < values.length;
            i++
        ) {

            if (
                String(
                    values[i] || ''
                )
                .toLowerCase()
                .indexOf(search) >= 0
            ) {

                return true;

            }

        }


        return false;

    };


    /* ============================================================
       FILTERS
       ============================================================ */

    c.matchesFilters = function(offer) {

        if (
            c.companyFilter &&
            offer.company !==
            c.companyFilter
        ) {

            return false;

        }


        if (
            c.roleFilter &&
            offer.jobRole !==
            c.roleFilter
        ) {

            return false;

        }


        return true;

    };


    /* ============================================================
       FILTERED OFFERS
       ============================================================ */

    c.getFilteredOffers = function() {

        if (
            !c.data ||
            !c.data.offers
        )
            return [];


        return c.data.offers.filter(
            function(offer) {

                return (
                    c.matchesSearch(
                        offer
                    ) &&
                    c.matchesFilters(
                        offer
                    )
                );

            }
        );

    };


    /* ============================================================
       CLEAR
       ============================================================ */

    c.clearFilters = function() {

        c.searchText = '';
        c.companyFilter = '';
        c.roleFilter = '';

    };


    /* ============================================================
       VIEW OFFER
       ============================================================ */

    c.viewOffer = function(offer) {

        if (!offer)
            return;

        c.selectedOffer = offer;

        c.showDocument = true;

    };


    /* ============================================================
       CLOSE OFFER
       ============================================================ */

    c.closeDocument = function() {

        c.showDocument = false;

        c.selectedOffer = null;

    };


    /* ============================================================
       DESTROY
       ============================================================ */

    $scope.$on(
        '$destroy',
        function() {

            c.selectedOffer = null;
            c.showDocument = false;

        }
    );

};

sp_widget.css:
/* ============================================================
   NEXORA OFFER LETTER
   ============================================================ */


/* ============================================================
   PAGE
   ============================================================ */

.nx-offer-page,
.nx-student-page {

    width: 100%;
    max-width: 1480px;

    margin: 0 auto;

    padding: 0 34px 50px;

    box-sizing: border-box;

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Arial,
        sans-serif;

    color: #193f5b;

}


/* ============================================================
   PAGE HEADER
   ============================================================ */

.nx-page-header {

    background: #193f5b;

    min-height: 165px;

    border-radius: 0 0 28px 28px;

    padding: 34px 40px;

    box-sizing: border-box;

    display: flex;

    align-items: center;

    justify-content: space-between;

    color: #ffffff;

    margin-bottom: 30px;

}


.nx-eyebrow {

    color: #ff725f;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;

    margin-bottom: 8px;

}


.nx-page-header h1 {

    margin: 0;

    font-size: 42px;

    line-height: 1.1;

    color: #ffffff;

    font-weight: 800;

}


.nx-page-header p {

    margin: 10px 0 0;

    color: #d7e1e9;

    font-size: 14px;

}


/* ============================================================
   STATISTICS
   ============================================================ */

.nx-stats-grid {

    display: grid;

    grid-template-columns:
        repeat(3, minmax(0, 1fr));

    gap: 20px;

    margin-bottom: 28px;

}


.nx-stat-card {

    min-height: 125px;

    background: #ffffff;

    border: 1px solid #dce5ec;

    border-radius: 16px;

    padding: 22px;

    display: flex;

    align-items: center;

    gap: 18px;

    box-sizing: border-box;

}


.nx-stat-icon {

    width: 54px;
    height: 54px;

    flex-shrink: 0;

    border-radius: 14px;

    background: #edf5ff;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 25px;

}


.nx-stat-card span {

    display: block;

    font-size: 10px;

    font-weight: 800;

    letter-spacing: 1.5px;

    color: #7790a5;

}


.nx-stat-card strong {

    display: block;

    margin-top: 4px;

    font-size: 28px;

    color: #193f5b;

}


.nx-stat-card small {

    display: block;

    margin-top: 2px;

    color: #879aaa;

    font-size: 11px;

}


/* ============================================================
   SCHEDULE CARD
   ============================================================ */

.nx-schedule-card {

    background: #ffffff;

    border: 1px solid #dce5ec;

    border-radius: 18px;

    overflow: hidden;

}


.nx-section-header {

    min-height: 88px;

    padding: 18px 28px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    border-bottom: 1px solid #e5ebf0;

}


.nx-section-title {

    display: flex;

    align-items: center;

    gap: 14px;

}


.nx-section-icon {

    width: 46px;
    height: 46px;

    border-radius: 12px;

    background: #193f5b;

    color: #ffffff;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 20px;

}


.nx-section-title h2 {

    margin: 0;

    font-size: 20px;

    color: #193f5b;

}


.nx-section-title p {

    margin: 3px 0 0;

    font-size: 12px;

    color: #8a9aaa;

}


.nx-record-count {

    background: #f3f6f8;

    color: #60768a;

    border-radius: 20px;

    padding: 9px 15px;

    font-size: 12px;

    font-weight: 700;

}


/* ============================================================
   FILTERS
   ============================================================ */

.nx-filter-bar {

    padding: 18px 28px;

    display: grid;

    grid-template-columns:
        minmax(300px, 1fr)
        190px
        180px
        75px;

    gap: 12px;

    border-bottom: 1px solid #e7edf2;

}


.nx-search {

    height: 44px;

    border: 1px solid #d6e0e8;

    border-radius: 10px;

    display: flex;

    align-items: center;

    padding: 0 13px;

    box-sizing: border-box;

}


.nx-search span {

    margin-right: 8px;

    font-size: 14px;

}


.nx-search input {

    border: none;

    outline: none;

    width: 100%;

    height: 100%;

    font-size: 13px;

    color: #193f5b;

}


.nx-search input::placeholder {

    color: #9aabb9;

}


.nx-select {

    height: 44px;

    border: 1px solid #d6e0e8;

    border-radius: 10px;

    background: #ffffff;

    padding: 0 12px;

    color: #526b80;

    outline: none;

}


.nx-clear-btn {

    height: 44px;

    border: 1px solid #d6e0e8;

    border-radius: 10px;

    background: #ffffff;

    color: #526b80;

    cursor: pointer;

}


.nx-clear-btn:hover {

    background: #f4f7f9;

}


/* ============================================================
   TABLE
   ============================================================ */

.nx-table-wrap {

    width: 100%;

    overflow-x: auto;

}


.nx-offer-table {

    width: 100%;

    border-collapse: collapse;

    min-width: 1050px;

}


.nx-offer-table th {

    height: 48px;

    padding: 0 16px;

    background: #f7f9fb;

    color: #7890a3;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.3px;

    text-align: left;

    white-space: nowrap;

}


.nx-offer-table td {

    height: 68px;

    padding: 0 16px;

    border-top: 1px solid #edf1f4;

    color: #526b80;

    font-size: 12px;

    white-space: nowrap;

}


.nx-offer-table tbody tr:hover {

    background: #fafcfd;

}


.nx-number {

    color: #193f5b;

}


.nx-student-cell {

    display: flex;

    align-items: center;

    gap: 10px;

}


.nx-student-cell strong {

    color: #294a63;

    font-size: 12px;

}


.nx-avatar {

    width: 36px;
    height: 36px;

    border-radius: 9px;

    background: #edf5ff;

    border: 1px solid #d1e3f7;

    color: #2771b7;

    display: flex;

    align-items: center;

    justify-content: center;

    font-weight: 800;

}


/* ============================================================
   STATUS
   ============================================================ */

.nx-status {

    display: inline-flex;

    align-items: center;

    padding: 5px 10px;

    border-radius: 7px;

    font-size: 10px;

    font-weight: 700;

}


.nx-status-offered {

    color: #16815d;

    background: #eaf9f2;

    border: 1px solid #c5eddc;

}


.nx-status-accepted {

    color: #1664a1;

    background: #eaf4ff;

    border: 1px solid #c8e1fa;

}


.nx-status-rejected {

    color: #a63b3b;

    background: #fff0f0;

    border: 1px solid #f2d0d0;

}


/* ============================================================
   VIEW BUTTON
   ============================================================ */

.nx-view-btn {

    border: 1px solid #c9dff1;

    background: #edf6ff;

    color: #236b9e;

    border-radius: 7px;

    padding: 7px 12px;

    font-size: 11px;

    font-weight: 700;

    cursor: pointer;

}


.nx-view-btn:hover {

    background: #dfefff;

}


/* ============================================================
   TABLE FOOTER
   ============================================================ */

.nx-table-footer {

    padding: 14px 20px;

    border-top: 1px solid #edf1f4;

    color: #8798a8;

    font-size: 11px;

}


/* ============================================================
   EMPTY
   ============================================================ */

.nx-empty {

    height: 220px !important;

    text-align: center !important;

}


.nx-empty div {

    font-size: 30px;

    margin-bottom: 8px;

}


.nx-empty strong {

    color: #526b80;

}


.nx-empty p {

    margin: 5px 0;

    color: #9aa9b6;

}


/* ============================================================
   STUDENT
   ============================================================ */

.nx-received-badge {

    padding: 10px 17px;

    border-radius: 10px;

    background: rgba(255,255,255,.1);

    border: 1px solid rgba(255,255,255,.2);

    color: #ffffff;

    font-size: 11px;

    font-weight: 700;

}


.nx-student-offer {

    background: #ffffff;

    border: 1px solid #dce5ec;

    border-radius: 18px;

    overflow: hidden;

}


.nx-congratulations {

    padding: 28px 32px;

    display: flex;

    align-items: center;

    gap: 18px;

    border-bottom: 1px solid #e5ebf0;

}


.nx-celebrate {

    width: 56px;
    height: 56px;

    background: #fff2ed;

    border: 1px solid #ffd8ce;

    border-radius: 15px;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 25px;

}


.nx-congratulations span {

    color: #ff725f;

    font-size: 10px;

    letter-spacing: 1.7px;

    font-weight: 800;

}


.nx-congratulations h2 {

    margin: 4px 0;

    color: #193f5b;

    font-size: 25px;

}


.nx-congratulations p {

    margin: 0;

    color: #8798a8;

    font-size: 13px;

}


.nx-student-company {

    padding: 28px 32px;

    display: flex;

    align-items: center;

    gap: 15px;

    border-bottom: 1px solid #e5ebf0;

}


.nx-company-icon {

    width: 54px;
    height: 54px;

    border-radius: 13px;

    background: #edf5ff;

    color: #2672b2;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 22px;

    font-weight: 800;

}


.nx-student-company span {

    color: #8497a8;

    font-size: 9px;

    letter-spacing: 1.5px;

    font-weight: 800;

}


.nx-student-company h2 {

    margin: 3px 0;

    color: #193f5b;

}


.nx-student-company p {

    margin: 0;

    color: #7890a3;

    font-size: 13px;

}


.nx-primary-view {

    margin-left: auto;

    background: #193f5b;

    color: #ffffff;

    border: none;

    border-radius: 9px;

    padding: 12px 18px;

    font-weight: 700;

    cursor: pointer;

}


.nx-primary-view:hover {

    background: #234d6b;

}


.nx-student-details {

    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

}


.nx-student-details > div {

    padding: 24px 28px;

    border-right: 1px solid #e5ebf0;

}


.nx-student-details > div:last-child {

    border-right: none;

}


.nx-student-details span {

    display: block;

    color: #8295a6;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.3px;

    margin-bottom: 7px;

}


.nx-student-details strong {

    color: #193f5b;

    font-size: 14px;

}


.nx-student-details small {

    font-size: 10px;

}


.nx-no-student-offer {

    min-height: 300px;

    background: #ffffff;

    border: 1px solid #dce5ec;

    border-radius: 18px;

    display: flex;

    align-items: center;

    justify-content: center;

    flex-direction: column;

    text-align: center;

}


.nx-no-student-offer > div {

    font-size: 35px;

}


.nx-no-student-offer h2 {

    color: #193f5b;

}


.nx-no-student-offer p {

    color: #8798a8;

}


/* ============================================================
   OFFER LETTER MODAL
   ============================================================ */

.nx-offer-modal-overlay {

    position: fixed;

    inset: 0;

    z-index: 999999;

    background: rgba(8, 27, 43, .72);

    display: flex;

    align-items: center;

    justify-content: center;

    padding: 25px;

    box-sizing: border-box;

}


.nx-offer-modal {

    width: min(1180px, 96vw);

    height: min(900px, 94vh);

    background: #ffffff;

    border-radius: 18px;

    overflow: hidden;

    box-shadow:
        0 25px 70px rgba(0,0,0,.30);

    display: flex;

    flex-direction: column;

}


.nx-offer-modal-header {

    min-height: 82px;

    flex-shrink: 0;

    padding: 17px 28px;

    box-sizing: border-box;

    background: #193f5b;

    color: #ffffff;

    display: flex;

    align-items: center;

    justify-content: space-between;

}


.nx-modal-label {

    color: #ff725f;

    font-size: 10px;

    font-weight: 800;

    letter-spacing: 2px;

}


.nx-offer-modal-header h2 {

    margin: 4px 0 0;

    color: #ffffff;

    font-size: 23px;

}


.nx-modal-close {

    width: 40px;
    height: 40px;

    border-radius: 9px;

    border: 1px solid rgba(255,255,255,.25);

    background: rgba(255,255,255,.08);

    color: #ffffff;

    font-size: 25px;

    cursor: pointer;

}


.nx-letter-scroll {

    flex: 1;

    min-height: 0;

    overflow-y: auto;

    background: #eef2f5;

    padding: 32px;

}


/* ============================================================
   LETTER PAPER
   ============================================================ */

.nx-letter {

    max-width: 860px;

    min-height: 1000px;

    margin: 0 auto;

    background: #ffffff;

    padding: 55px 62px;

    box-sizing: border-box;

    box-shadow:
        0 8px 30px rgba(0,0,0,.10);

    border: 1px solid #e0e7ec;

}


/* ============================================================
   LETTER HEADER
   ============================================================ */

.nx-letter-header {

    display: flex;

    justify-content: space-between;

    align-items: flex-start;

}


.nx-letter-company-block {

    display: flex;

    align-items: center;

    gap: 13px;

}


.nx-letter-logo {

    width: 50px;
    height: 50px;

    border-radius: 10px;

    background: #193f5b;

    color: #ffffff;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 22px;

    font-weight: 800;

}


.nx-letter-company {

    font-size: 19px;

    font-weight: 800;

    color: #193f5b;

}


.nx-letter-company-sub {

    margin-top: 3px;

    font-size: 8px;

    color: #8798a8;

    letter-spacing: 1.5px;

    font-weight: 700;

}


.nx-letter-meta {

    text-align: right;

}


.nx-letter-meta div {

    margin-bottom: 9px;

}


.nx-letter-meta span {

    display: block;

    font-size: 8px;

    color: #899aaa;

    letter-spacing: 1.3px;

    font-weight: 800;

}


.nx-letter-meta strong {

    display: block;

    margin-top: 3px;

    font-size: 11px;

    color: #193f5b;

}


/* ============================================================
   LETTER TITLE
   ============================================================ */

.nx-letter-divider {

    height: 1px;

    background: #dfe6eb;

    margin: 28px 0 38px;

}


.nx-letter-title {

    text-align: center;

    margin-bottom: 38px;

}


.nx-letter-title h1 {

    margin: 0;

    color: #193f5b;

    font-size: 21px;

    letter-spacing: 1px;

    font-weight: 800;

}


.nx-letter-title div {

    width: 60px;

    height: 3px;

    border-radius: 3px;

    background: #ff725f;

    margin: 12px auto 0;

}


/* ============================================================
   LETTER BODY
   ============================================================ */

.nx-letter-content {

    color: #43596b;

    font-size: 13px;

    line-height: 1.85;

}


.nx-letter-content p {

    margin: 0 0 20px;

}


.nx-letter-content strong {

    color: #193f5b;

}


/* ============================================================
   DETAILS
   ============================================================ */

.nx-letter-details {

    display: grid;

    grid-template-columns: 1fr 1fr;

    border: 1px solid #dce5eb;

    border-radius: 10px;

    overflow: hidden;

    margin: 28px 0;

}


.nx-letter-details > div {

    padding: 15px 18px;

    border-bottom: 1px solid #dce5eb;

}


.nx-letter-details > div:nth-child(odd) {

    border-right: 1px solid #dce5eb;

}


.nx-letter-details > div:nth-last-child(-n+2) {

    border-bottom: none;

}


.nx-letter-details span {

    display: block;

    color: #8497a7;

    font-size: 8px;

    letter-spacing: 1.3px;

    font-weight: 800;

    margin-bottom: 5px;

}


.nx-letter-details strong {

    font-size: 12px;

    color: #193f5b;

}


/* ============================================================
   SIGNATURE
   ============================================================ */

.nx-letter-signature {

    margin-top: 42px;

}


.nx-letter-signature p {

    margin-bottom: 4px;

}


.nx-letter-signature strong {

    display: block;

    color: #193f5b;

}


.nx-letter-signature span {

    color: #8192a1;

    font-size: 11px;

}


/* ============================================================
   LETTER FOOTER
   ============================================================ */

.nx-letter-footer {

    margin-top: 60px;

    padding-top: 15px;

    border-top: 1px solid #dfe6eb;

    display: flex;

    justify-content: space-between;

    color: #8a9aa8;

    font-size: 8px;

    letter-spacing: 1px;

    text-transform: uppercase;

}


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 1000px) {

    .nx-filter-bar {

        grid-template-columns:
            1fr 1fr;

    }

    .nx-search {

        grid-column: 1 / -1;

    }

    .nx-student-details {

        grid-template-columns: 1fr 1fr;

    }

}


@media (max-width: 700px) {

    .nx-offer-page,
    .nx-student-page {

        padding: 0 15px 30px;

    }

    .nx-page-header {

        padding: 25px;

    }

    .nx-page-header h1 {

        font-size: 30px;

    }

    .nx-stats-grid {

        grid-template-columns: 1fr;

    }

    .nx-filter-bar {

        grid-template-columns: 1fr;

    }

    .nx-search {

        grid-column: auto;

    }

    .nx-student-company {

        flex-wrap: wrap;

    }

    .nx-primary-view {

        width: 100%;

        margin-left: 0;

    }

    .nx-student-details {

        grid-template-columns: 1fr;

    }

    .nx-student-details > div {

        border-right: none;

        border-bottom: 1px solid #e5ebf0;

    }

    .nx-offer-modal-overlay {

        padding: 8px;

    }

    .nx-offer-modal {

        width: 100%;

        height: 97vh;

    }

    .nx-letter-scroll {

        padding: 12px;

    }

    .nx-letter {

        padding: 35px 25px;

    }

    .nx-letter-header {

        flex-direction: column;

        gap: 20px;

    }

    .nx-letter-meta {

        text-align: left;

    }

    .nx-letter-details {

        grid-template-columns: 1fr;

    }

    .nx-letter-details > div:nth-child(odd) {

        border-right: none;

    }

    .nx-letter-details > div:nth-last-child(-n+2) {

        border-bottom: 1px solid #dce5eb;

    }

}

sp_widget.link:
api.controller = function($scope) {

    var c = this;


    c.searchText = '';
    c.companyFilter = '';
    c.roleFilter = '';

    c.selectedOffer = null;

    c.showDocument = false;

    c.isLoading = false;


    /*
     * INITIALIZE
     */
    c.$onInit = function() {

        if (!c.data)
            return;


        if (!c.data.offers)
            c.data.offers = [];


        if (!c.data.stats) {

            c.data.stats = {

                total: 0,

                thisMonth: 0,

                companies: 0

            };

        }

    };


    /*
     * ADMIN TABLE VIEW
     *
     * TPO
     * Interviewer
     */
    c.isTPO = function() {

        return !!(
            c.data &&
            (
                c.data.isTPO ||
                c.data.isInterviewer
            )
        );

    };


    /*
     * COMPANY USER
     *
     * ONLY INTERVIEWER
     */
    c.isCompanyUser = function() {

        return !!(
            c.data &&
            c.data.isInterviewer
        );

    };


    /*
     * STUDENT OFFER EXISTS
     */
    c.hasOffer = function() {

        return !!(
            c.data &&
            c.data.offer
        );

    };


    /*
     * OFFERED STATUS
     */
    c.isOffered = function() {

        if (!c.hasOffer())
            return false;


        var status =
            String(
                c.data.offer.status || ''
            )
            .toLowerCase()
            .trim();


        return (
            status === 'offered' ||
            status === 'accepted' ||
            status === 'offer accepted'
        );

    };


    /*
     * ACCEPTED STATUS
     */
    c.isAccepted = function() {

        if (!c.hasOffer())
            return false;


        var status =
            String(
                c.data.offer.status || ''
            )
            .toLowerCase()
            .trim();


        return (
            status === 'accepted' ||
            status === 'offer accepted'
        );

    };


    /*
     * STATUS CSS
     */
    c.getStatusClass = function(status) {

        status =
            String(
                status || 'offered'
            )
            .toLowerCase()
            .trim();


        if (
            status === 'accepted' ||
            status === 'offer accepted'
        ) {

            return 'nx-status-accepted';

        }


        if (
            status === 'rejected' ||
            status === 'declined'
        ) {

            return 'nx-status-rejected';

        }


        return 'nx-status-offered';

    };


    /*
     * STATUS LABEL
     */
    c.getStatusLabel = function(status) {

        return status || 'Offered';

    };


    /*
     * STUDENT INITIAL
     */
    c.getInitial = function(name) {

        if (!name)
            return 'O';


        return String(name)
            .trim()
            .charAt(0)
            .toUpperCase();

    };


    /*
     * DISPLAY VALUE
     */
    c.displayValue = function(
        value,
        fallback
    ) {

        if (
            value === null ||
            typeof value === 'undefined' ||
            String(value).trim() === ''
        ) {

            return fallback ||
                'Not specified';

        }


        return value;

    };


    /*
     * COMPANY LIST
     *
     * USED BY TPO ONLY
     */
    c.getCompanies = function() {

        var result = {};

        var companies = [];


        if (
            !c.data ||
            !c.data.offers
        ) {

            return companies;

        }


        c.data.offers.forEach(
            function(offer) {

                if (
                    offer.company &&
                    !result[
                        offer.company
                    ]
                ) {

                    result[
                        offer.company
                    ] = true;


                    companies.push(
                        offer.company
                    );

                }

            }
        );


        return companies.sort();

    };


    /*
     * ROLE LIST
     */
    c.getRoles = function() {

        var result = {};

        var roles = [];


        if (
            !c.data ||
            !c.data.offers
        ) {

            return roles;

        }


        c.data.offers.forEach(
            function(offer) {

                if (
                    offer.jobRole &&
                    !result[
                        offer.jobRole
                    ]
                ) {

                    result[
                        offer.jobRole
                    ] = true;


                    roles.push(
                        offer.jobRole
                    );

                }

            }
        );


        return roles.sort();

    };


    /*
     * SEARCH
     */
    c.matchesSearch = function(
        offer
    ) {

        var search =
            String(
                c.searchText || ''
            )
            .toLowerCase()
            .trim();


        if (!search)
            return true;


        var values = [

            offer.number,

            offer.student,

            offer.company,

            offer.jobRole,

            offer.package,

            offer.offerDate

        ];


        for (
            var i = 0;
            i < values.length;
            i++
        ) {

            if (
                String(
                    values[i] || ''
                )
                .toLowerCase()
                .indexOf(search) >= 0
            ) {

                return true;

            }

        }


        return false;

    };


    /*
     * FILTERS
     */
    c.matchesFilters = function(
        offer
    ) {

        /*
         * COMPANY FILTER
         *
         * ONLY TPO CAN USE IT.
         *
         * Interviewer already receives
         * only their company records
         * from the Server Script.
         */
        if (
            !c.isCompanyUser() &&
            c.companyFilter &&
            offer.company !==
                c.companyFilter
        ) {

            return false;

        }


        /*
         * ROLE FILTER
         */
        if (
            c.roleFilter &&
            offer.jobRole !==
                c.roleFilter
        ) {

            return false;

        }


        return true;

    };


    /*
     * FILTERED OFFERS
     */
    c.getFilteredOffers = function() {

        if (
            !c.data ||
            !c.data.offers
        ) {

            return [];

        }


        return c.data.offers.filter(
            function(offer) {

                return (
                    c.matchesSearch(
                        offer
                    ) &&
                    c.matchesFilters(
                        offer
                    )
                );

            }
        );

    };


    /*
     * CLEAR FILTERS
     */
    c.clearFilters = function() {

        c.searchText = '';

        c.companyFilter = '';

        c.roleFilter = '';

    };


    /*
     * VIEW OFFER
     */
    c.viewOffer = function(
        offer
    ) {

        if (!offer)
            return;


        c.selectedOffer =
            offer;


        c.showDocument =
            true;

    };


    /*
     * CLOSE OFFER
     */
    c.closeDocument = function() {

        c.showDocument =
            false;


        c.selectedOffer =
            null;

    };


    /*
     * CLEANUP
     */
    $scope.$on(
        '$destroy',
        function() {

            c.selectedOffer =
                null;


            c.showDocument =
                false;

        }
    );

};

sp_widget.script:
(function() {

    /* ============================================================
       NEXORA - OFFER LETTER WIDGET
       SERVER SCRIPT
       TPO + INTERVIEWER + STUDENT
       ============================================================ */

    var OFFER_TABLE =
        'x_snc_college_pl_0_offer_letter';

    var STUDENT_TABLE =
        'x_snc_college_pl_0_student';

    var COMPANY_TABLE =
        'x_snc_college_pl_0_company';

    var TPO_ROLE =
        'x_snc_college_pl_0.placement_admin';

    var INTERVIEWER_ROLE =
        'x_snc_college_pl_0.interviewer';


    /* ============================================================
       ROLE
       ============================================================ */

    data.isTPO =
        gs.hasRole(TPO_ROLE);

    data.isInterviewer =
        gs.hasRole(INTERVIEWER_ROLE);


    data.offers = [];
    data.offer = null;
    data.error = '';


    data.stats = {
        total: 0,
        thisMonth: 0,
        companies: 0
    };


    /* ============================================================
       HELPER
       ============================================================ */

    function getValue(gr, field) {

        if (!gr.isValidField(field))
            return '';

        return gr.getDisplayValue(field) || '';

    }


    /* ============================================================
       FIND COMPANY FOR INTERVIEWER

       IMPORTANT:
       This uses Company.hr_user to identify
       the company associated with the logged-in
       Interviewer.
       ============================================================ */

    var companyIds = [];

    var companyGR =
        new GlideRecord(COMPANY_TABLE);

    if (companyGR.isValid()) {

        companyGR.addQuery(
            'hr_user',
            gs.getUserID()
        );

        companyGR.query();

        while (companyGR.next()) {

            companyIds.push(
                companyGR.getUniqueValue()
            );

        }

    }


    /* ============================================================
       FIND STUDENT
       ============================================================ */

    var studentSysId = '';

    var studentGR =
        new GlideRecord(STUDENT_TABLE);

    if (studentGR.isValid()) {

        if (
            studentGR.isValidField('user')
        ) {

            studentGR.addQuery(
                'user',
                gs.getUserID()
            );

            studentGR.setLimit(1);

            studentGR.query();

            if (studentGR.next()) {

                studentSysId =
                    studentGR.getUniqueValue();

            }

        }

    }


    /* ============================================================
       OFFER TABLE
       ============================================================ */

    var offerGR =
        new GlideRecord(OFFER_TABLE);

    if (!offerGR.isValid()) {

        data.error =
            'Offer Letter table not found: ' +
            OFFER_TABLE;

        return;

    }


    /* ============================================================
       ACCESS CONTROL
       ============================================================ */


    /*
     * TPO
     *
     * ORIGINAL BEHAVIOR:
     * TPO sees ALL offer letters.
     */

    if (data.isTPO) {

        // DO NOT ADD ANY FILTER.
        // TPO sees everything.


    }


    /*
     * INTERVIEWER
     *
     * Interviewer sees ONLY their
     * associated company's offers.
     */

    else if (data.isInterviewer) {

        if (companyIds.length === 0) {

            data.error =
                'No company is associated with this interviewer.';

            return;

        }


        if (
            !offerGR.isValidField('company')
        ) {

            data.error =
                'Company field not found in Offer Letter table.';

            return;

        }


        offerGR.addQuery(
            'company',
            'IN',
            companyIds.join(',')
        );

    }


    /*
     * STUDENT
     *
     * Original student behavior.
     */

    else {

        if (!studentSysId) {

            data.error =
                'Student profile not found for the logged-in user.';

            return;

        }


        if (
            !offerGR.isValidField('student')
        ) {

            data.error =
                'Student field not found in Offer Letter table.';

            return;

        }


        offerGR.addQuery(
            'student',
            studentSysId
        );

    }


    /* ============================================================
       ORDER
       ============================================================ */

    if (
        offerGR.isValidField('offer_date')
    ) {

        offerGR.orderByDesc(
            'offer_date'
        );

    } else {

        offerGR.orderByDesc(
            'sys_created_on'
        );

    }


    offerGR.query();


    /* ============================================================
       BUILD OFFER DATA
       ============================================================ */

    var companyMap = {};


    while (offerGR.next()) {

        var offer = {};


        offer.sys_id =
            offerGR.getUniqueValue();


        offer.number =
            getValue(
                offerGR,
                'offer_number'
            );


        offer.student =
            getValue(
                offerGR,
                'student'
            );


        offer.company =
            getValue(
                offerGR,
                'company'
            );


        offer.jobRole =
            getValue(
                offerGR,
                'job_role'
            );


        offer.package =
            getValue(
                offerGR,
                'package'
            );


        offer.offerDate =
            getValue(
                offerGR,
                'offer_date'
            );


        offer.joiningDate =
            getValue(
                offerGR,
                'joining_date'
            );


        /*
         * STATUS IS ONLY READ.
         * NOTHING IS CHANGED.
         */

        offer.status =
            getValue(
                offerGR,
                'status'
            );


        if (!offer.status) {

            offer.status =
                'Offered';

        }


        /* ========================================================
           APPLICATION
           ======================================================== */

        if (
            offerGR.isValidField(
                'application'
            )
        ) {

            offer.application =
                getValue(
                    offerGR,
                    'application'
                );

        } else {

            offer.application = '';

        }


        /* ========================================================
           COMPANY COUNT
           ======================================================== */

        if (
            offer.company &&
            !companyMap[
                offer.company
            ]
        ) {

            companyMap[
                offer.company
            ] = true;

        }


        data.offers.push(
            offer
        );

    }


    /* ============================================================
       STATISTICS
       ============================================================ */

    data.stats.total =
        data.offers.length;


    var now =
        new GlideDateTime();


    var currentMonth =
        now.getYearLocalTime() +
        '-' +
        now.getMonthLocalTime();


    var monthCount = 0;


    for (
        var i = 0;
        i < data.offers.length;
        i++
    ) {

        var offerDate =
            data.offers[i].offerDate;


        if (offerDate) {

            var dateString =
                String(offerDate);


            if (
                dateString.indexOf(
                    currentMonth
                ) === 0
            ) {

                monthCount++;

            }

        }

    }


    data.stats.thisMonth =
        monthCount;


    data.stats.companies =
        Object.keys(
            companyMap
        ).length;


    /* ============================================================
       STUDENT OFFER
       ============================================================ */

    if (
        !data.isTPO &&
        !data.isInterviewer
    ) {

        if (
            data.offers.length > 0
        ) {

            data.offer =
                data.offers[0];

        }

    }

})();
